{"filepath":"fib_cache.py","content":""""
Simple Fibonacci implementations: naive recursive, cached recursive using lru_cache,
and an iterative high-performance reference. Type hinted and documented.
"""
from functools import lru_cache
from typing import Dict


def naive_recursive(n: int) -> int:
    """Compute Fibonacci using the naive recursion.

    Warning: exponential time; only suitable for small n.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return naive_recursive(n - 1) + naive_recursive(n - 2)


@lru_cache(maxsize=None)
def cached_recursive(n: int) -> int:
    """Compute Fibonacci using recursion with memoization (lru_cache).

    Faster than naive recursion, but still recursive so very large n can hit
    Python's recursion limit (~1000 by default).
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return cached_recursive(n - 1) + cached_recursive(n - 2)


def iterative(n: int) -> int:
    """Compute Fibonacci iteratively in O(n) time and O(1) extra space.

    This is the recommended approach for large n.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


# Optional utility: compute multiple fibs at once
def fibs_up_to(n: int) -> Dict[int, int]:
    """Return a dict of Fibonacci numbers for 0..n using the iterative method."""
    result: Dict[int, int] = {}
    a, b = 0, 1
    for i in range(n + 1):
        result[i] = a
        a, b = b, a + b
    return result
